INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('website-development','Website Development','Website Development','We provide professional website development services designed to help businesses establish a strong and impactful online presence. Our websites are built with modern technologies, clean coding standards, and performance optimization to ensure speed, security, and scalability.','Website Development — NFS Tech','Professional website development services with modern tech, clean code, and performance optimization.','Website Development Packages','/one time',0);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('wordpress-development','WordPress Development','WordPress Development','We design and develop modern, high-performance WordPress websites tailored to help your business grow online. From startups to established companies, we create fully responsive, fast-loading, and SEO-friendly websites that reflect your brand identity and convert visitors into customers.','WordPress Development — NFS Tech','Modern, fast-loading, SEO-friendly WordPress websites tailored to your brand.','WordPress Development Packages','/one time',1);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('shopify-store','Shopify Store','Shopify Store','We create fully functional Shopify stores that are designed to boost sales, engage customers, and grow your brand online. Whether you''re a startup, small business, or established brand, we provide end-to-end Shopify solutions including store setup, custom design, product integration, payment gateway setup, and ongoing support.','Shopify Store Development — NFS Tech','Fully functional Shopify stores built to boost sales, engage customers, and grow your brand.','Shopify Store Packages','/one time',2);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('app-development','App Development','Mobile App Development','We provide professional mobile app development services designed to help businesses connect with customers anytime, anywhere. From startup ideas to full-scale business applications, we build powerful, user-friendly, and scalable mobile apps tailored to your goals.','Mobile App Development — NFS Tech','Powerful, user-friendly, scalable mobile apps for Android and iOS tailored to your goals.','Mobile App Development Packages','/one time',3);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('software-development','Software Development','Software Development','We provide custom software development services designed to streamline operations, improve efficiency, and accelerate business growth. Our solutions are tailored to meet specific business requirements, ensuring scalability, security, and long-term performance.','Custom Software Development — NFS Tech','Custom software development to streamline operations, improve efficiency and accelerate growth.','Software Development Packages','/one time',4);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('e-commerce-store','E-Commerce Store','E-Commerce Store','We design and develop powerful eCommerce stores that help businesses sell products online effortlessly. Our stores are built to provide an amazing shopping experience, increase conversions, and grow your brand.','E-Commerce Store Development — NFS Tech','Powerful eCommerce stores that help businesses sell products online and increase conversions.','E-commerce Store Packages','/one time',5);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('seo','SEO','SEO — Search Engine Optimization','We provide professional SEO services designed to boost your website''s visibility, attract more organic traffic, and increase your business revenue.','SEO Services — NFS Tech','Boost visibility, attract organic traffic, and increase revenue with professional SEO services.','SEO Packages','/monthly',6);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('digital-marketing','Digital Marketing','Digital Marketing','Comprehensive digital marketing services tailored to help your business grow online.','Digital Marketing Services — NFS Tech','Data-driven digital marketing that drives traffic, generates leads, and increases sales.','Digital Marketing Packages','/monthly',7);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('google-ads','Google Ads','Google Ads Management','Result-driven Google Ads management services designed to generate high-quality leads.','Google Ads Management — NFS Tech','Result-driven Google Ads management to generate high-quality leads, traffic, and sales.','Google Ads Packages','/monthly',8);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('meta-ads','Meta Ads','Meta Ads Management','Professional Meta Ads management to grow leads and brand awareness on Facebook and Instagram.','Meta Ads Management — NFS Tech','Highly targeted Facebook & Instagram advertising to generate leads and grow brand awareness.','Meta Ads Packages','/monthly',9);
INSERT INTO public.services (slug, title, heading, intro, meta_title, meta_desc, pricing_label, price_suffix, sort_order) VALUES ('social-media-marketing','Social Media Marketing','Social Media Marketing','Strategic Social Media Marketing to grow your brand and generate real business results.','Social Media Marketing — NFS Tech','Strategic social media marketing to grow your brand, engagement, and real business results.','Social Media Management Packages','/monthly',10);
