INSERT INTO public.faqs (question, answer, sort_order) VALUES ('What services does NFS Tech offer?','We offer website development, WordPress, Shopify, mobile app & software development, SEO, digital marketing, graphic design and domain & hosting services.',0);
INSERT INTO public.faqs (question, answer, sort_order) VALUES ('How long does it take to build a website?','Delivery ranges from 7 days for basic sites to 21+ days for premium custom builds.',1);
INSERT INTO public.faqs (question, answer, sort_order) VALUES ('Do you provide ongoing support?','Yes — every package includes free support ranging from 1 to 3 months, with paid extensions available.',2);
INSERT INTO public.faqs (question, answer, sort_order) VALUES ('Can I customize a package?','Absolutely. Contact us via WhatsApp and we''ll craft a custom plan that fits your requirements.',3);
INSERT INTO public.faqs (question, answer, sort_order) VALUES ('Do you offer refunds?','We offer milestone-based delivery. Refunds are handled case-by-case per contract terms.',4);
