INSERT INTO public.site_content (key, value) VALUES ('about','{"body": "NFS Tech (Next Feature Solution Technology) has been building websites, apps and brands since 2020. We help startups and enterprises grow online with modern technology and creative design.", "title": "About NFS Tech"}'::jsonb);
